root = '/home/user/Experiment-3/.claude/worktrees/wf_466ee687-d89-1/'


def edit(path, pairs):
    p = root + path
    s = open(p).read()
    for a, b in pairs:
        assert s.count(a) == 1, (path, a[:90])
        s = s.replace(a, b)
    open(p, 'w').write(s)


